import '../../../../core/constants/firestore_paths.dart'; import '../../../../core/services/firebase_firestore_service.dart'; import '../models/teacher_leave_model.dart';
abstract class TeacherLeaveRemoteDataSource { Future<List<TeacherLeaveModel>> getLeaves(); Future<void> save(TeacherLeaveModel leave); String generateId(); }
class TeacherLeaveRemoteDataSourceImpl implements TeacherLeaveRemoteDataSource { TeacherLeaveRemoteDataSourceImpl({required FirebaseFirestoreService firestoreService}):_service=firestoreService; final FirebaseFirestoreService _service; @override Future<List<TeacherLeaveModel>> getLeaves()async{final snapshot=await _service.collection(FirestorePaths.teacherLeaves).orderBy('createdAt',descending:true).get();return snapshot.docs.map((doc)=>TeacherLeaveModel.fromMap({...doc.data(),'id':doc.id})).toList();} @override Future<void> save(TeacherLeaveModel leave)=>_service.collection(FirestorePaths.teacherLeaves).doc(leave.id).set(leave.toMap()); @override String generateId()=>_service.collection(FirestorePaths.teacherLeaves).doc().id; }
